def transform(grid):
    from collections import deque
    g=[row[:] for row in grid]
    R=len(g); C=len(g[0])
    outside=set(); q=deque()
    for r in range(R):
        for c in range(C):
            if g[r][c]==0 and (r==0 or r==R-1 or c==0 or c==C-1):
                outside.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<R and 0<=nc<C and g[nr][nc]==0 and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))
    hole=[(r,c) for r in range(R) for c in range(C) if g[r][c]==0 and (r,c) not in outside]
    if not hole: return g
    rs=[r for r,c in hole]; cs=[c for r,c in hole]
    cr=(min(rs)+max(rs))//2; cc=(min(cs)+max(cs))//2
    color=next(g[r][c] for r in range(R) for c in range(C) if g[r][c]!=0)
    g[cr][cc]=color
    return g

